  ('landing.hero.calendar_mock_paid_note', 'de', 'Dieser Kalender ist illustrativ. Mit kostenpflichtigem Plan ist die vollständige Kalenderspalte in der App für Pro-Nutzer; in der Gratis-Stufe stehen Liste und nächste Zahlungen im Fokus.'),
  ('landing.hero.calendar_mock_paid_note', 'en', 'This calendar is illustrative. When a paid plan is on, the full payment calendar column in the app is for Pro users; on the free tier you still manage the list and upcoming charges.'),
  ('landing.hero.calendar_mock_paid_note', 'es', 'Este calendario es ilustrativo. Con el plan de pago, la columna completa del calendario en la app es para usuarios Pro; en el nivel gratuito gestionas la lista y los próximos cobros.'),
  ('landing.hero.calendar_mock_paid_note', 'fr', 'Ce calendrier est illustratif. Avec l’offre payante, la colonne calendrier complète dans l’app est réservée aux comptes Pro ; en accès gratuit, vous gardez liste et prochains paiements.'),
  ('landing.hero.calendar_mock_paid_note', 'lv', 'Kalendārs šeit ir ilustratīvs. Ja ieslēgts maksas plāns, pilna maksājumu kalendāra kolonna panelī ir Pro lietotājiem; brīvajā līmenī koncentrējies uz sarakstu un nākamajiem maksājumiem.'),
  ('landing.hero.calendar_mock_paid_note', 'pt', 'Este calendário é ilustrativo. Com o plano pago, a coluna completa do calendário na app é para utilizadores Pro; no nível gratuito continua a gerir a lista e os próximos pagamentos.'),
  ('landing.hero.calendar_mock_paid_note', 'ru', 'Этот календарь для примера. При платном плане полная колонка календаря в приложении - для Pro; на бесплатном уровне вы ведёте список и ближайшие платежи.'),
