  ('subscribe.hero.lead', 'de', 'Unbegrenzte Einträge, Erinnerungen und voller Zahlungskalender an einem Ort. Etwa so viel wie ein Kaffee im Monat — und dir entgeht keine Zahlung.'),
  ('subscribe.hero.lead', 'en', 'Unlimited entries, reminders, and a full payment calendar in one place. About the price of a coffee a month — and you never forget your payments.'),
  ('subscribe.hero.lead', 'es', 'Entradas ilimitadas, recordatorios y calendario de pagos completo en un sitio. Alrededor del precio de un café al mes — y nunca olvidas tus pagos.'),
  ('subscribe.hero.lead', 'fr', 'Entrées illimitées, rappels et calendrier des paiements complet au même endroit. À peu près le prix d’un café par mois — et vous n’oubliez jamais vos paiements.'),
  ('subscribe.hero.lead', 'lv', 'Neierobežoti ieraksti, atgādinājumi un pilns maksājumu kalendārs vienā vietā. Aptuveni tikpat cik viena kafija mēnesī — un tu nekad neaizmirsti savus maksājumus.'),
  ('subscribe.hero.lead', 'pt', 'Entradas ilimitadas, lembretes e calendário completo de pagamentos num só sítio. Por volta do preço de um café por mês — e nunca te esqueces dos teus pagamentos.'),
  ('subscribe.hero.lead', 'ru', 'Неограниченные записи, напоминания и полный календарь платежей в одном месте. Примерно как чашка кофе в месяц — и вы никогда не забываете о своих платежах.'),
